mapper.select:
SELECT b.id, b.name, b.description, b.color, b.status, COUNT(bm2.member_id) AS member_count FROM boards b JOIN board_members bm ON b.id = bm.board_id AND bm.member_id = #{memberId} AND bm.board_role IN ('USER', 'MANAGER') LEFT JOIN board_members bm2 ON b.id = bm2.board_id AND bm2.board_role IN ('USER', 'MANAGER') WHERE b.status = #{status}
AND b.name LIKE CONCAT('%', #{keyword}, '%')
GROUP BY b.id

