mapper.select:
SELECT b.id, b.name, b.description, b.color, b.status, COUNT(bm2.member_id) AS member_count, bm_me.board_role AS my_role FROM boards b LEFT JOIN board_members bm_me ON b.id = bm_me.board_id AND bm_me.member_id = #{memberId} LEFT JOIN board_members bm2 ON b.id = bm2.board_id AND bm2.board_role IN ('USER', 'MANAGER')
b.name LIKE CONCAT('%', #{q}, '%') AND b.status = #{status}
GROUP BY b.id
ORDER BY member_count DESC, b.id DESC ORDER BY b.id DESC
LIMIT #{size} OFFSET #{offset}
